using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class FinishVerify {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B4_Finish/";static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};static string Id(UnityEngine.Object o)=>GlobalObjectId.GetGlobalObjectIdSlow(o).ToString();
 static bool Eq(JToken a,JToken b){if(a==null||b==null)return a==null&&b==null;if(a is JValue&&b is JValue){if(a.Type==JTokenType.Float||a.Type==JTokenType.Integer)return Math.Abs((double)a-(double)b)<.00002;return JToken.DeepEquals(a,b);}return a.Children().Count()==b.Children().Count()&&a.Children().Zip(b.Children(),Eq).All(x=>x);}
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("Saved B4 edit required");var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var state=JArray.FromObject(ts.Select(t=>new{id=Id(t),name=t.name,parent=t.parent?Id(t.parent):"",p=V(t.localPosition),e=V(t.localEulerAngles),scale=V(t.localScale),active=t.gameObject.activeSelf,colliders=t.GetComponents<Collider>().Select(c=>new{id=Id(c),c.enabled,c.isTrigger,type=c.GetType().Name,mesh=c is MeshCollider mc&&mc.sharedMesh?AssetDatabase.GetAssetPath(mc.sharedMesh):"",boxCenter=c is BoxCollider bc?V(bc.center):null,boxSize=c is BoxCollider bb?V(bb.size):null})}));var map=state.ToDictionary(j=>(string)j["id"]);var old=JArray.Parse(File.ReadAllText(H+"state_before.json"));var diffs=new List<object>();foreach(var j in old){if(!map.TryGetValue((string)j["id"],out var cur)){diffs.Add(new{id=(string)j["id"],key="missing"});continue;}foreach(string key in new[]{"name","parent","p","e","scale","active","colliders"})if(!Eq(j[key],cur[key]))diffs.Add(new{name=(string)j["name"],key,before=j[key],after=cur[key]});}
 var allowedWalls=JArray.Parse(File.ReadAllText(H+"walls_applied.json")).Select(q=>(string)q["id"]).ToHashSet();int missing=0,meshChanged=0;foreach(var p in JArray.Parse(File.ReadAllText(H+"renderers_before.json"))){GlobalObjectId.TryParse((string)p["id"],out var gid);var mr=GlobalObjectId.GlobalObjectIdentifierToObjectSlow(gid) as MeshRenderer;if(!mr){missing++;continue;}var m=mr.GetComponent<MeshFilter>().sharedMesh;if(!allowedWalls.Contains((string)p["id"])&&(m.name!=(string)p["mesh"]||AssetDatabase.GetAssetPath(m)!=(string)p["asset"]))meshChanged++;}
 var rs=ts.SelectMany(t=>t.GetComponents<MeshRenderer>()).ToArray();var groups=ts.SelectMany(t=>t.GetComponents<LODGroup>()).ToArray();var result=new{originalTransforms=old.Count,stateDifferences=diffs,originalRenderersMissing=missing,unexpectedOriginalMeshesChanged=meshChanged,lodGroups=groups.Length,lodBad=groups.Count(g=>g.GetLODs().Length!=3||g.GetLODs().Any(l=>l.renderers.Any(r=>!r))),missingMaterials=rs.Sum(r=>r.sharedMaterials.Count(m=>!m)),extraCollision=ts.Where(t=>t.name.StartsWith("Distance_LOD")).Sum(t=>t.GetComponents<Collider>().Length),probes=ts.Sum(t=>t.GetComponents<ReflectionProbe>().Length),lights=ts.Sum(t=>t.GetComponents<Light>().Length),scene=s.path,dirty=s.isDirty};File.WriteAllText(H+"state_after.json",state.ToString());File.WriteAllText(R+"/Docs/Review/2026-11-09_B4_Finish/verification.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
